public class XmppPipeline extends ChannelInitializer<Channel> {

    private final ConnectionListener eventListener;
    private final Debugger debugger;
    private final SyncStreamRestart sync;
    private final EventExecutorGroup listenerThreadPool;

    public XmppPipeline(ConnectionListener eventListener, SyncStreamRestart sync, EventExecutorGroup listenerExector) {
        this(eventListener, sync, listenerExector, null);
    }

    public XmppPipeline(ConnectionListener eventListener, SyncStreamRestart sync,
            EventExecutorGroup listenerThreadPool, Debugger debugger) {
        this.eventListener = eventListener;
        this.sync = sync;
        this.debugger = debugger;
        this.listenerThreadPool = listenerThreadPool;
    }

    @Override
    public void initChannel(Channel ch) {
        ch.pipeline().addLast(new XmlEventDecoder(sync), new XmppEventDecoder(debugger));
        ch.pipeline().addLast(listenerThreadPool, new XmppEventDispatcher(eventListener));

        if (debugger != null) {
            ch.pipeline().addLast(new DebugHandler(debugger));
        }
        ch.pipeline().addLast(new XmppEncoder());
    }
}

